// Originally generated by Lovable; now maintained by hand (demo mode below).
import { createClient } from "@supabase/supabase-js";
import type { Database } from "./types";
import { isDemo } from "@/lib/demo/mode";

function createSupabaseClient() {
  // Use import.meta.env for client-side (Vite build-time replacement)
  // Fall back to process.env for SSR (server-side rendering)
  const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL || process.env.SUPABASE_URL;
  const SUPABASE_PUBLISHABLE_KEY =
    import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY || process.env.SUPABASE_PUBLISHABLE_KEY;

  if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
    const missing = [
      ...(!SUPABASE_URL ? ["SUPABASE_URL"] : []),
      ...(!SUPABASE_PUBLISHABLE_KEY ? ["SUPABASE_PUBLISHABLE_KEY"] : []),
    ];
    const message = `Missing Supabase environment variable(s): ${missing.join(", ")}. Connect Supabase in Lovable Cloud.`;
    console.error(`[Supabase] ${message}`);
    throw new Error(message);
  }

  return createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
    auth: {
      storage: typeof window !== "undefined" ? localStorage : undefined,
      persistSession: true,
      autoRefreshToken: true,
    },
  });
}

/**
 * The demo workspace's client: same API, but every request is answered in the
 * browser by src/lib/demo/server.ts (loaded on first use) and the session is a
 * fixed demo one that never touches the real login in localStorage.
 */
function createDemoClient() {
  const DEMO_AUTH_KEY = "flowform-demo-auth";
  const backend = () => import("@/lib/demo/server");
  return createClient<Database>(
    import.meta.env.VITE_SUPABASE_URL || "https://demo.supabase.co",
    import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY || "demo",
    {
      auth: {
        storageKey: DEMO_AUTH_KEY,
        storage: {
          getItem: async (key) =>
            key === DEMO_AUTH_KEY ? JSON.stringify((await backend()).demoSession()) : null,
          setItem: async () => {},
          removeItem: async () => {},
        },
        persistSession: true,
        autoRefreshToken: false,
        detectSessionInUrl: false,
      },
      global: { fetch: async (input, init) => (await backend()).handle(input, init) },
    },
  );
}

let _supabase: ReturnType<typeof createSupabaseClient> | undefined;
let _demo: boolean | undefined;

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";
// Lazy Proxy: the real client (and env-var validation) is initialized on first
// property access, not at import time. If env vars are missing, the error will
// surface at the first supabase.from/auth/... call rather than at module load.
export const supabase = new Proxy({} as ReturnType<typeof createSupabaseClient>, {
  get(_, prop, receiver) {
    _demo ??= isDemo();
    if (!_supabase) _supabase = _demo ? createDemoClient() : createSupabaseClient();
    return Reflect.get(_supabase, prop, receiver);
  },
});
